    acph->dtphr = picokdt_getDtPHR(thiz->voice->kbArray[PICOKNOW_KBID_DT_PHR]);
    if (acph->dtphr == NULL) {
        return picoos_emRaiseException(thiz->common->em, PICO_EXC_KB_MISSING,
                                       NULL, NULL);
    }
    ;

     
    acph->dtacc = picokdt_getDtACC(thiz->voice->kbArray[PICOKNOW_KBID_DT_ACC]);
