        case PICODATA_ITEM_FRAME_PAR:
            tmpstr = (picoos_char *)PICO_S(30);
            break;
        case PICODATA_ITEM_PHONE:
            tmpstr = (picoos_char *)PICO_S(31);
            break;
        case PICODATA_ITEM_CMD:
            tmpstr = (picoos_char *)PICO_S(32);
            break;
        case PICODATA_ITEM_ERR:
            tmpstr = (picoos_char *)PICO_S(33);
            break;
        case PICODATA_ITEM_FRAME:
            tmpstr = (picoos_char *)PICO_S(34);
            break;
        case PICODATA_ITEM_OTHER:
            tmpstr = (picoos_char *)PICO_S(35);
            break;
        case PICODATA_ITEM_PUNC:
            tmpstr = (picoos_char *)PICO_S(36);
            break;
        case PICODATA_ITEM_SYLLPHON:
            tmpstr = (picoos_char *)PICO_S(37);
            break;
        case PICODATA_ITEM_WORDGRAPH:
            tmpstr = (picoos_char *)PICO_S(38);
            break;
        case PICODATA_ITEM_WORDINDEX:
            tmpstr = (picoos_char *)PICO_S(39);
